%matplotlib inline
from specter.trust import BetaTrustEvaluator, CohortEvent
from specter.telemetry import ReputationTrace
from specter.viz.notebook import (
    cohort_timeline, triangulation_2d, reputation_sparkline,
)

# Honest case: three observers, each reporting their true range to a subject at (3, 3).
observer_positions = {
    'observer1': (0.0, 0.0),
    'observer2': (6.0, 0.0),
    'observer3': (3.0, 6.0),
}
# True ranges from each observer to (3, 3) ≈ {4.24, 4.24, 3.0}; add small noise.
honest_pending = {
    ('subject', 1_000_000_000): [
        ('observer1', 4.25),
        ('observer2', 4.21),
        ('observer3', 3.02),
    ]
}
fig = triangulation_2d(honest_pending, observer_positions=observer_positions)
